import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';
import { cn } from '../../../utils/cn';
import { useToast } from '../../../contexts/ToastContext';
import { formatLuc, formatNaira, lucToNaira } from '../../../utils/currencyUtils';

const AdminPayoutControl = () => {
    const { addToast } = useToast();
    const [requests, setRequests] = useState([]);
    const [lucRequests, setLucRequests] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [processingId, setProcessingId] = useState(null);
    const [referenceMap, setReferenceMap] = useState({});
    const [adminNotesMap, setAdminNotesMap] = useState({});
    const [activeTab, setActiveTab] = useState('naira');

    useEffect(() => {
        fetchAllData();
    }, []);

    const fetchAllData = async () => {
        setIsLoading(true);
        try {
            const [payoutData, lucData] = await Promise.all([
                supabaseService.getAdminPayoutRequests(),
                supabaseService.getAllLucWithdrawals()
            ]);
            setRequests(payoutData);
            setLucRequests(lucData);
        } catch (error) {
            console.error('Failed to fetch payout data:', error);
            addToast('Failed to load financial data.', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleNairaStatusUpdate = async (id, status) => {
        setProcessingId(id);
        try {
            const reference = referenceMap[id] || '';
            await supabaseService.updatePayoutStatus(id, status, reference);
            addToast(`Payout marked as ${status} successfully.`, 'success');
            fetchAllData();
        } catch (error) {
            console.error('Failed to update payout:', error);
            addToast('Action failed. Please try again.', 'error');
        } finally {
            setProcessingId(null);
        }
    };

    const handleLucStatusUpdate = async (id, status) => {
        setProcessingId(id);
        try {
            const notes = adminNotesMap[id] || '';
            await supabaseService.updateLucWithdrawalStatus(id, status, notes);
            addToast(`LUC withdrawal marked as ${status}.`, 'success');
            fetchAllData();
        } catch (error) {
            console.error('Failed to update LUC withdrawal:', error);
            addToast('Action failed. Please try again.', 'error');
        } finally {
            setProcessingId(null);
        }
    };

    const nairaStats = {
        pendingCount: requests.filter(r => r.status === 'pending').length,
        pendingAmount: requests.filter(r => r.status === 'pending').reduce((acc, r) => acc + r.amount, 0),
        totalPaid: requests.filter(r => r.status === 'paid').reduce((acc, r) => acc + r.amount, 0)
    };

    const lucStats = {
        pendingCount: lucRequests.filter(r => r.status === 'pending').length,
        pendingLuc: lucRequests.filter(r => r.status === 'pending').reduce((acc, r) => acc + r.amount_luc, 0),
        totalCompletedLuc: lucRequests.filter(r => r.status === 'completed').reduce((acc, r) => acc + r.amount_luc, 0),
        totalCompletedNaira: lucRequests.filter(r => r.status === 'completed').reduce((acc, r) => acc + r.amount_naira, 0)
    };

    if (isLoading) {
        return (
            <div className="py-20 flex justify-center">
                <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin" />
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
            {/* Tab Navigation */}
            <div className="flex gap-2 p-1 bg-muted/50 rounded-2xl w-fit">
                <button
                    onClick={() => setActiveTab('naira')}
                    className={cn(
                        "px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all",
                        activeTab === 'naira' 
                            ? "bg-primary text-primary-foreground shadow-lg" 
                            : "text-muted-foreground hover:text-foreground"
                    )}
                >
                    Naira Payouts ({nairaStats.pendingCount})
                </button>
                <button
                    onClick={() => setActiveTab('luc')}
                    className={cn(
                        "px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all",
                        activeTab === 'luc' 
                            ? "bg-indigo-600 text-white shadow-lg" 
                            : "text-muted-foreground hover:text-foreground"
                    )}
                >
                    LUC Withdrawals ({lucStats.pendingCount})
                </button>
            </div>

            {activeTab === 'naira' ? (
                <>
                    {/* Naira Financial Overview */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        {[
                            { label: 'Pending Requests', value: nairaStats.pendingCount, icon: 'Clock', color: 'text-amber-500', bg: 'bg-amber-500/10' },
                            { label: 'Pending Volume', value: `₦${nairaStats.pendingAmount.toLocaleString()}`, icon: 'Wallet', color: 'text-secondary', bg: 'bg-secondary/10' },
                            { label: 'Total Paid Out', value: `₦${nairaStats.totalPaid.toLocaleString()}`, icon: 'CheckCircle', color: 'text-success', bg: 'bg-success/10' }
                        ].map((item, i) => (
                            <div key={i} className="p-6 bg-card border border-border rounded-[2.5rem] shadow-sm">
                                <div className={cn("w-12 h-12 rounded-2xl flex items-center justify-center mb-4", item.bg, item.color)}>
                                    <Icon name={item.icon} size={24} />
                                </div>
                                <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mb-1">{item.label}</p>
                                <p className={cn("text-2xl font-black italic", item.color)}>
                                    {item.value}
                                </p>
                            </div>
                        ))}
                    </div>

                    {/* Naira Payout List */}
                    <div className="bg-card border border-border rounded-[2.5rem] overflow-hidden">
                        <div className="p-6 border-b border-border bg-muted/20 flex items-center justify-between">
                            <div>
                                <h4 className="font-black text-primary italic">Instructor Payout Queue</h4>
                                <p className="text-xs text-muted-foreground font-medium italic">Review and process fund transfers for LUC Academy Educators.</p>
                            </div>
                            <Button variant="ghost" size="sm" iconName="RefreshCw" onClick={fetchAllData}>Refresh Queue</Button>
                        </div>
                        
                        <div className="overflow-x-auto">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="bg-muted/10 text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground">
                                        <th className="px-6 py-4">Instructor</th>
                                        <th className="px-6 py-4">Amount</th>
                                        <th className="px-6 py-4">Method</th>
                                        <th className="px-6 py-4">Status</th>
                                        <th className="px-6 py-4">Action / Reference</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-border">
                                    {requests.map((request) => (
                                        <tr key={request.id} className="hover:bg-muted/5 transition-colors group">
                                            <td className="px-6 py-4">
                                                <div className="flex items-center gap-3">
                                                    <div className="w-10 h-10 rounded-xl bg-slate-900 border border-white/5 overflow-hidden flex-shrink-0">
                                                        <img 
                                                            src={request.instructor?.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(request.instructor?.full_name)}&background=random`} 
                                                            className="w-full h-full object-cover" 
                                                        />
                                                    </div>
                                                    <div>
                                                        <p className="font-bold text-sm text-primary italic">{request.instructor?.full_name}</p>
                                                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">Requested: {new Date(request.created_at).toLocaleDateString()}</p>
                                                    </div>
                                                </div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <span className="text-sm font-black italic text-primary">₦{request.amount.toLocaleString()}</span>
                                            </td>
                                            <td className="px-6 py-4">
                                                <div className="flex flex-col gap-1">
                                                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{request.payout_method}</span>
                                                    {request.payout_method === 'Bank Transfer' && (
                                                        <p className="text-[9px] text-muted-foreground font-medium italic truncate max-w-[150px]">
                                                            Account: {request.metadata?.account_number || 'See Application'}
                                                        </p>
                                                    )}
                                                </div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <span className={cn(
                                                    "px-2 py-1 rounded-full text-[8px] font-black tracking-widest uppercase",
                                                    request.status === 'pending' ? "bg-amber-500/10 text-amber-500 border border-amber-500/20" :
                                                    request.status === 'paid' ? "bg-success/10 text-success border border-success/20" :
                                                    "bg-destructive/10 text-destructive border border-destructive/20"
                                                )}>
                                                    {request.status}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4">
                                                {request.status === 'pending' ? (
                                                    <div className="flex items-center gap-3">
                                                        <div className="flex-1 min-w-[150px]">
                                                            <Input 
                                                                placeholder="Payment Ref (e.g. Bank ID)" 
                                                                className="h-8 text-[10px]"
                                                                value={referenceMap[request.id] || ''}
                                                                onChange={(e) => setReferenceMap({ ...referenceMap, [request.id]: e.target.value })}
                                                            />
                                                        </div>
                                                        <Button 
                                                            variant="default" 
                                                            size="sm" 
                                                            className="h-8 px-4 text-[10px] font-black italic bg-success hover:bg-success/80 text-white"
                                                            isLoading={processingId === request.id}
                                                            onClick={() => handleNairaStatusUpdate(request.id, 'paid')}
                                                        >
                                                            MARK AS PAID
                                                        </Button>
                                                        <Button 
                                                            variant="ghost" 
                                                            size="sm" 
                                                            className="h-8 text-[10px] text-destructive hover:bg-destructive/10 font-black italic"
                                                            onClick={() => handleNairaStatusUpdate(request.id, 'failed')}
                                                        >
                                                            REJECT
                                                        </Button>
                                                    </div>
                                                ) : (
                                                    <p className="text-[10px] text-slate-400 font-medium italic">
                                                        {request.status === 'paid' ? `Processed: ${new Date(request.processed_at).toLocaleDateString()} (${request.metadata?.payment_reference || 'No Ref'})` : 'Request Rejected'}
                                                    </p>
                                                )}
                                            </td>
                                        </tr>
                                    ))}
                                    {requests.length === 0 && (
                                        <tr>
                                            <td colSpan="5" className="px-6 py-12 text-center">
                                                <Icon name="Inbox" size={48} className="mx-auto text-muted-foreground opacity-20 mb-4" />
                                                <p className="text-sm text-muted-foreground italic font-medium">No payout requests in the queue.</p>
                                            </td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </>
            ) : (
                <>
                    {/* LUC Withdrawal Stats */}
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                        {[
                            { label: 'Pending Requests', value: lucStats.pendingCount, icon: 'Clock', color: 'text-amber-500', bg: 'bg-amber-500/10' },
                            { label: 'Pending LUC', value: `${formatAmount(lucStats.pendingLuc)} LUC`, icon: 'Coins', color: 'text-indigo-500', bg: 'bg-indigo-500/10' },
                            { label: 'Pending Value', value: formatNaira(lucToNaira(lucStats.pendingLuc)), icon: 'Wallet', color: 'text-secondary', bg: 'bg-secondary/10' },
                            { label: 'Total Completed', value: `${formatAmount(lucStats.totalCompletedLuc)} LUC`, icon: 'CheckCircle', color: 'text-success', bg: 'bg-success/10' }
                        ].map((item, i) => (
                            <div key={i} className="p-6 bg-card border border-border rounded-[2.5rem] shadow-sm">
                                <div className={cn("w-12 h-12 rounded-2xl flex items-center justify-center mb-4", item.bg, item.color)}>
                                    <Icon name={item.icon} size={24} />
                                </div>
                                <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mb-1">{item.label}</p>
                                <p className={cn("text-2xl font-black italic", item.color)}>
                                    {item.value}
                                </p>
                            </div>
                        ))}
                    </div>

                    {/* LUC Withdrawal List */}
                    <div className="bg-card border border-border rounded-[2.5rem] overflow-hidden">
                        <div className="p-6 border-b border-border bg-muted/20 flex items-center justify-between">
                            <div>
                                <h4 className="font-black text-indigo-500 italic">LUC Credit Withdrawal Queue</h4>
                                <p className="text-xs text-muted-foreground font-medium italic">Review and process LUC credit withdrawal requests from students and instructors.</p>
                            </div>
                            <Button variant="ghost" size="sm" iconName="RefreshCw" onClick={fetchAllData}>Refresh Queue</Button>
                        </div>
                        
                        <div className="overflow-x-auto">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="bg-muted/10 text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground">
                                        <th className="px-6 py-4">User</th>
                                        <th className="px-6 py-4">Amount (LUC)</th>
                                        <th className="px-6 py-4">Value (₦)</th>
                                        <th className="px-6 py-4">Bank Details</th>
                                        <th className="px-6 py-4">Status</th>
                                        <th className="px-6 py-4">Action / Notes</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-border">
                                    {lucRequests.map((request) => (
                                        <tr key={request.id} className="hover:bg-muted/5 transition-colors group">
                                            <td className="px-6 py-4">
                                                <div className="flex items-center gap-3">
                                                    <div className="w-10 h-10 rounded-xl bg-indigo-600 border border-white/5 overflow-hidden flex-shrink-0">
                                                        <img 
                                                            src={request.user?.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(request.user?.full_name)}&background=random`} 
                                                            className="w-full h-full object-cover" 
                                                        />
                                                    </div>
                                                    <div>
                                                        <p className="font-bold text-sm text-primary italic">{request.user?.full_name}</p>
                                                        <div className="flex items-center gap-2">
                                                            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">
                                                                {new Date(request.created_at).toLocaleDateString()}
                                                            </p>
                                                            <span className={cn(
                                                                "text-[8px] font-black uppercase px-1.5 py-0.5 rounded",
                                                                request.user?.role === 'instructor' 
                                                                    ? "bg-secondary/10 text-secondary" 
                                                                    : "bg-primary/10 text-primary"
                                                            )}>
                                                                {request.user?.role || 'student'}
                                                            </span>
                                                        </div>
                                                    </div>
                                                </div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <span className="text-sm font-black italic text-indigo-500">{formatAmount(request.amount_luc)} LUC</span>
                                            </td>
                                            <td className="px-6 py-4">
                                                <span className="text-sm font-bold text-slate-500">≈ {formatNaira(request.amount_naira)}</span>
                                            </td>
                                            <td className="px-6 py-4">
                                                <div className="flex flex-col gap-0.5">
                                                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{request.bank_details?.bank_name || 'N/A'}</span>
                                                    <p className="text-[9px] text-muted-foreground font-mono tracking-wider">{request.bank_details?.account_number || 'N/A'}</p>
                                                    <p className="text-[9px] text-muted-foreground font-medium italic truncate max-w-[120px]">{request.bank_details?.account_name || 'N/A'}</p>
                                                </div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <span className={cn(
                                                    "px-2 py-1 rounded-full text-[8px] font-black tracking-widest uppercase",
                                                    request.status === 'pending' ? "bg-amber-500/10 text-amber-500 border border-amber-500/20" :
                                                    request.status === 'completed' ? "bg-success/10 text-success border border-success/20" :
                                                    request.status === 'processing' ? "bg-blue-500/10 text-blue-500 border border-blue-500/20" :
                                                    "bg-destructive/10 text-destructive border border-destructive/20"
                                                )}>
                                                    {request.status}
                                                </span>
                                                {request.processed_at && (
                                                    <p className="text-[9px] text-slate-400 mt-1 font-medium italic">
                                                        {new Date(request.processed_at).toLocaleDateString()}
                                                    </p>
                                                )}
                                            </td>
                                            <td className="px-6 py-4">
                                                {request.status === 'pending' ? (
                                                    <div className="flex flex-col gap-2">
                                                        <Input 
                                                            placeholder="Admin notes (optional)" 
                                                            className="h-8 text-[10px]"
                                                            value={adminNotesMap[request.id] || ''}
                                                            onChange={(e) => setAdminNotesMap({ ...adminNotesMap, [request.id]: e.target.value })}
                                                        />
                                                        <div className="flex items-center gap-2">
                                                            <Button 
                                                                variant="default" 
                                                                size="sm" 
                                                                className="h-8 px-3 text-[10px] font-black italic bg-success hover:bg-success/80 text-white"
                                                                isLoading={processingId === request.id}
                                                                onClick={() => handleLucStatusUpdate(request.id, 'completed')}
                                                            >
                                                                <Icon name="Check" size={12} className="mr-1" />
                                                                APPROVE
                                                            </Button>
                                                            <Button 
                                                                variant="ghost" 
                                                                size="sm" 
                                                                className="h-8 px-3 text-[10px] text-destructive hover:bg-destructive/10 font-black italic"
                                                                onClick={() => handleLucStatusUpdate(request.id, 'failed')}
                                                            >
                                                                REJECT
                                                            </Button>
                                                        </div>
                                                    </div>
                                                ) : (
                                                    <p className="text-[10px] text-slate-400 font-medium italic">
                                                        {request.admin_notes || 'No notes'}
                                                    </p>
                                                )}
                                            </td>
                                        </tr>
                                    ))}
                                    {lucRequests.length === 0 && (
                                        <tr>
                                            <td colSpan="6" className="px-6 py-12 text-center">
                                                <Icon name="Inbox" size={48} className="mx-auto text-muted-foreground opacity-20 mb-4" />
                                                <p className="text-sm text-muted-foreground italic font-medium">No LUC withdrawal requests in the queue.</p>
                                            </td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </>
            )}
        </div>
    );

    function formatAmount(amount) {
        return new Intl.NumberFormat().format(amount);
    }
};

export default AdminPayoutControl;