import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';

const ScholarshipManagement = () => {
    const [scholars, setScholars] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const { addToast } = useToast();
    const academyCourses = useSelector((state) => state.content.academy) || [];

    useEffect(() => {
        fetchScholars();
    }, []);

    const fetchScholars = async () => {
        setIsLoading(true);
        try {
            // Fetch scholarships directly from enrollments where amount_paid is 0
            const { data: scholarshipEnrollments, error } = await supabaseService.supabase
                .from('enrollments')
                .select('*')
                .eq('amount_paid', 0);
                
            if (error) throw error;
            
            // For each scholarship, fetch the student's progress and profile
            const richScholars = await Promise.all((scholarshipEnrollments || []).map(async (enrollment) => {
                const studentId = enrollment.user_id;
                const courseId = enrollment.item_id;

                // Fetch profile
                const profile = await supabaseService.getProfile(studentId).catch(() => null);
                
                // Fetch progress from lesson_progress to get granular data, or use enrollment progress
                const { data: progressData } = await supabaseService.supabase
                    .from('user_progress')
                    .select('progress_percentage, last_accessed_at, status')
                    .eq('user_id', studentId)
                    .eq('course_id', courseId)
                    .maybeSingle();

                const course = academyCourses.find(c => String(c.id) === String(courseId)) || { title: 'LUC Sponsored Course' };

                return {
                    id: enrollment.id,
                    student: profile || { full_name: 'Unknown Student', avatar_url: null, id: studentId },
                    course: course,
                    awardedAt: enrollment.created_at || new Date().toISOString(),
                    progress: progressData?.progress_percentage || enrollment.progress || 0,
                    status: progressData?.status || enrollment.status || 'started',
                    lastActive: progressData?.last_accessed_at || enrollment.updated_at || new Date().toISOString()
                };
            }));

            setScholars(richScholars.sort((a, b) => new Date(b.awardedAt) - new Date(a.awardedAt)));
        } catch (error) {
            console.error("Failed to fetch scholars:", error);
            addToast("Could not load scholarship data", "error");
        } finally {
            setIsLoading(false);
        }
    };

    const stats = [
        { label: 'Total Awarded', value: scholars.length, icon: 'Award', color: 'text-primary' },
        { label: 'Active Learners', value: scholars.filter(s => s.status !== 'completed').length, icon: 'BookOpen', color: 'text-secondary' },
        { label: 'Mastered', value: scholars.filter(s => s.status === 'completed').length, icon: 'CheckCircle', color: 'text-success' },
        { label: 'Avg. Progress', value: `${Math.round(scholars.reduce((acc, s) => acc + s.progress, 0) / (scholars.length || 1))}%`, icon: 'TrendingUp', color: 'text-brand-blue' }
    ];

    return (
        <div className="space-y-6 md:space-y-8 p-4 md:p-6 overflow-hidden animate-in fade-in duration-500">
            {/* Stats Overview */}
            <div className="grid grid-cols-2 sm:grid-cols-2 md:grid-cols-4 gap-3 md:gap-4">
                {stats.map((stat, i) => (
                    <div key={i} className="bg-card border border-border p-3 sm:p-6 rounded-2xl md:rounded-3xl shadow-sm space-y-2">
                        <div className="flex items-center justify-between text-muted-foreground">
                            <span className="text-[10px] font-black uppercase tracking-widest">{stat.label}</span>
                            <Icon name={stat.icon} size={16} className={stat.color} />
                        </div>
                        <p className="text-xl sm:text-3xl font-black italic tracking-tighter">{stat.value}</p>
                    </div>
                ))}
            </div>

            {/* Scholars Table */}
            <div className="bg-card border border-border rounded-2xl md:rounded-[2.5rem] overflow-hidden shadow-xl">
                <div className="p-4 md:p-8 border-b border-border flex flex-col sm:flex-row sm:items-center justify-between gap-3 bg-muted/20">
                    <div>
                        <h2 className="text-lg sm:text-xl font-black italic tracking-tight">Merit Scholarship Tracker</h2>
                        <p className="text-xs text-muted-foreground font-medium">Monitor the impact of your sponsorships and student progress.</p>
                    </div>
                    <Button variant="ghost" iconName="RefreshCw" onClick={fetchScholars} disabled={isLoading}>
                        Refresh Data
                    </Button>
                </div>

                {/* Mobile Card View */}
                <div className="md:hidden divide-y divide-border/50">
                    {isLoading ? (
                        Array(3).fill(0).map((_, i) => (
                            <div key={i} className="p-4 space-y-3 animate-pulse">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 bg-muted rounded-xl" />
                                    <div className="space-y-2 flex-1">
                                        <div className="h-4 w-32 bg-muted rounded-lg" />
                                        <div className="h-3 w-48 bg-muted rounded-lg" />
                                    </div>
                                </div>
                                <div className="h-4 w-full bg-muted rounded-full" />
                            </div>
                        ))
                    ) : scholars.length === 0 ? (
                        <div className="p-12 text-center text-muted-foreground font-medium">
                            <div className="flex flex-col items-center gap-3">
                                <div className="w-12 h-12 bg-muted rounded-full flex items-center justify-center">
                                    <Icon name="Search" size={24} />
                                </div>
                                No scholarships awarded yet.
                            </div>
                        </div>
                    ) : (
                        scholars.map((scholar) => (
                            <div key={scholar.id} className="p-4 space-y-3">
                                <div className="flex items-center justify-between gap-2">
                                    <div className="flex items-center gap-3 min-w-0">
                                        <img 
                                            src={scholar.student.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(scholar.student.full_name)}&background=random`} 
                                            alt={scholar.student.full_name}
                                            className="w-10 h-10 rounded-xl object-cover shrink-0"
                                        />
                                        <div className="min-w-0">
                                            <p className="font-bold text-sm truncate">{scholar.student.full_name}</p>
                                            <p className="text-[10px] text-muted-foreground uppercase tracking-widest font-black">ID: {scholar.student.id?.substring(0, 8)}</p>
                                        </div>
                                    </div>
                                    <span className={`
                                        text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full shrink-0
                                        ${scholar.status === 'completed' ? 'bg-success/10 text-success' : 'bg-secondary/10 text-secondary'}
                                    `}>
                                        {scholar.status === 'completed' ? 'Mastered' : 'Learning'}
                                    </span>
                                </div>
                                <div>
                                    <p className="text-sm font-bold line-clamp-1">{scholar.course.title}</p>
                                    <span className="text-[10px] px-1.5 py-0.5 bg-primary/10 text-primary font-bold rounded uppercase tracking-tighter">Academy</span>
                                </div>
                                <div className="w-full space-y-1">
                                    <div className="flex items-center justify-between text-[10px] font-black italic">
                                        <span>{scholar.progress}%</span>
                                        <span className="text-muted-foreground uppercase">Mastery</span>
                                    </div>
                                    <div className="h-1.5 w-full bg-muted rounded-full overflow-hidden">
                                        <div 
                                            className="h-full bg-gradient-to-r from-primary to-secondary transition-all duration-1000"
                                            style={{ width: `${scholar.progress}%` }}
                                        />
                                    </div>
                                </div>
                                <div className="flex items-center justify-between text-xs text-muted-foreground">
                                    <span>Awarded: {new Date(scholar.awardedAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}</span>
                                    <span>Last active: {scholar.lastActive ? new Date(scholar.lastActive).toLocaleDateString() : 'Never'}</span>
                                </div>
                            </div>
                        ))
                    )}
                </div>

                {/* Desktop Table View */}
                <div className="hidden md:block overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="bg-muted/30 text-[10px] font-black uppercase tracking-widest text-muted-foreground border-b border-border">
                                <th className="px-8 py-4">LUC Scholar</th>
                                <th className="px-6 py-4">Sponsored Course</th>
                                <th className="px-6 py-4">Awarded On</th>
                                <th className="px-6 py-4">Learning Progress</th>
                                <th className="px-6 py-4">Status</th>
                                <th className="px-8 py-4 text-right">Last Active</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border/50">
                            {isLoading ? (
                                Array(3).fill(0).map((_, i) => (
                                    <tr key={i} className="animate-pulse">
                                        <td className="px-8 py-6"><div className="h-8 w-32 bg-muted rounded-lg" /></td>
                                        <td className="px-6 py-6"><div className="h-8 w-48 bg-muted rounded-lg" /></td>
                                        <td className="px-6 py-6"><div className="h-8 w-24 bg-muted rounded-lg" /></td>
                                        <td className="px-6 py-6"><div className="h-4 w-full bg-muted rounded-full" /></td>
                                        <td className="px-6 py-6"><div className="h-6 w-20 bg-muted rounded-full" /></td>
                                        <td className="px-8 py-6 text-right"><div className="h-8 w-24 ml-auto bg-muted rounded-lg" /></td>
                                    </tr>
                                ))
                            ) : scholars.length === 0 ? (
                                <tr>
                                    <td colSpan="6" className="px-8 py-12 text-center text-muted-foreground font-medium">
                                        <div className="flex flex-col items-center gap-3">
                                            <div className="w-12 h-12 bg-muted rounded-full flex items-center justify-center">
                                                <Icon name="Search" size={24} />
                                            </div>
                                            No scholarships awarded yet. Start sponsoring students to see their progress here!
                                        </div>
                                    </td>
                                </tr>
                            ) : (
                                scholars.map((scholar) => (
                                    <tr key={scholar.id} className="hover:bg-muted/20 transition-colors group">
                                        <td className="px-8 py-5">
                                            <div className="flex items-center gap-3">
                                                <img 
                                                    src={scholar.student.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(scholar.student.full_name)}&background=random`} 
                                                    alt={scholar.student.full_name}
                                                    className="w-10 h-10 rounded-xl object-cover ring-2 ring-transparent group-hover:ring-primary/20 transition-all"
                                                />
                                                <div>
                                                    <p className="font-bold text-sm">{scholar.student.full_name}</p>
                                                    <p className="text-[10px] text-muted-foreground uppercase tracking-widest font-black">ID: {scholar.student.id?.substring(0, 8)}</p>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-6 py-5">
                                            <div className="space-y-1">
                                                <p className="text-sm font-bold line-clamp-1">{scholar.course.title}</p>
                                                <span className="text-[10px] px-1.5 py-0.5 bg-primary/10 text-primary font-bold rounded uppercase tracking-tighter">Academy</span>
                                            </div>
                                        </td>
                                        <td className="px-6 py-5">
                                            <p className="text-xs font-medium text-muted-foreground">
                                                {new Date(scholar.awardedAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}
                                            </p>
                                        </td>
                                        <td className="px-6 py-5">
                                            <div className="w-full space-y-2">
                                                <div className="flex items-center justify-between text-[10px] font-black italic">
                                                    <span>{scholar.progress}%</span>
                                                    <span className="text-muted-foreground uppercase">Mastery</span>
                                                </div>
                                                <div className="h-1.5 w-full bg-muted rounded-full overflow-hidden">
                                                    <div 
                                                        className="h-full bg-gradient-to-r from-primary to-secondary transition-all duration-1000"
                                                        style={{ width: `${scholar.progress}%` }}
                                                    />
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-6 py-5">
                                            <span className={`
                                                text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full
                                                ${scholar.status === 'completed' ? 'bg-success/10 text-success' : 'bg-secondary/10 text-secondary'}
                                            `}>
                                                {scholar.status === 'completed' ? 'Mastered' : 'Learning'}
                                            </span>
                                        </td>
                                        <td className="px-8 py-5 text-right">
                                            <p className="text-xs font-medium text-muted-foreground">
                                                {scholar.lastActive ? new Date(scholar.lastActive).toLocaleDateString() : 'Never'}
                                            </p>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Impact Quote */}
            <div className="bg-gradient-to-br from-primary/5 to-secondary/5 border border-primary/10 rounded-2xl md:rounded-3xl p-4 md:p-8 flex flex-col sm:flex-row items-center gap-4 sm:gap-6">
                <div className="w-12 h-12 sm:w-16 sm:h-16 bg-white dark:bg-[#0f172a] rounded-2xl flex items-center justify-center shadow-lg shrink-0">
                    <Icon name="Quote" size={28} className="text-primary" />
                </div>
                <div className="text-center sm:text-left">
                    <h4 className="text-base sm:text-lg font-black italic tracking-tight">"Education is the most powerful weapon which you can use to change the world."</h4>
                    <p className="text-xs text-muted-foreground font-medium mt-1">— Nelson Mandela. Your sponsorships are making this a reality.</p>
                </div>
            </div>
        </div>
    );
};

export default ScholarshipManagement;
