import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { supabaseService } from '../../../services/supabaseService';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import Modal from '../../../components/ui/Modal';
import { useToast } from '../../../contexts/ToastContext';

const extractYouTubeId = (url) => {
    if (!url) return null;
    const trimmed = url.trim();
    if (/^[a-zA-Z0-9_-]{11}$/.test(trimmed)) return trimmed;
    const patterns = [
        /(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/|youtube\.com\/v\/|youtube\.com\/shorts\/)([a-zA-Z0-9_-]{11})/,
        /^https?:\/\/(?:www\.)?youtube\.com\/watch\?.*v=([a-zA-Z0-9_-]{11})/,
    ];
    for (const pat of patterns) {
        const match = trimmed.match(pat);
        if (match) return match[1];
    }
    return null;
};

const LinkRecordingModal = ({ isOpen, onClose, onLinked, track, course, existingRecording }) => {
    const { addToast } = useToast();
    const user = useSelector((state) => state.auth.user);
    const [youtubeUrl, setYoutubeUrl] = useState('');
    const [isValid, setIsValid] = useState(false);
    const [videoId, setVideoId] = useState(null);
    const [saving, setSaving] = useState(false);
    const [removing, setRemoving] = useState(false);

    useEffect(() => {
        if (existingRecording?.youtube_video_id) {
            setYoutubeUrl(`https://www.youtube.com/watch?v=${existingRecording.youtube_video_id}`);
        } else {
            setYoutubeUrl('');
        }
        setIsValid(false);
        setVideoId(null);
    }, [existingRecording, isOpen]);

    useEffect(() => {
        const id = extractYouTubeId(youtubeUrl);
        setVideoId(id);
        setIsValid(!!id);
    }, [youtubeUrl]);

    const handleSave = async () => {
        if (!videoId) {
            addToast('Please enter a valid YouTube URL', 'error');
            return;
        }
        setSaving(true);
        try {
            await supabaseService.upsertCourseRecording({
                trackId: track.id,
                courseId: String(course.id),
                liveSessionId: existingRecording?.live_session_id || null,
                youtubeVideoId: videoId,
                recordedAt: new Date().toISOString(),
                createdBy: user?.id,
            });
            addToast(`Recording linked to "${course.title}"`, 'success');

            // Notify enrolled students
            try {
                const trackCourseIds = (track.courses || []).map(String);
                await supabaseService.notifyTrackStudentsPrivateChat({
                    trackCourseIds,
                    message: `🎬 Recording Available: The recording for "${course.title}" is now available! Head to the course to watch the full class session.`
                });
            } catch (notifyErr) {
                console.error('Failed to notify students:', notifyErr);
            }

            onLinked();
        } catch (err) {
            console.error('Failed to link recording:', err);
            addToast('Failed to link recording', 'error');
        } finally {
            setSaving(false);
        }
    };

    const handleRemove = async () => {
        setRemoving(true);
        try {
            await supabaseService.deleteCourseRecording(String(course.id));
            addToast(`Recording removed from "${course.title}"`, 'success');
            onLinked();
        } catch (err) {
            addToast('Failed to remove recording', 'error');
        } finally {
            setRemoving(false);
        }
    };

    return (
        <Modal isOpen={isOpen} onClose={onClose} title="Link YouTube Recording" size="md">
            <div className="space-y-6">
                <div className="bg-muted/30 rounded-xl p-4 border border-border">
                    <p className="text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1">Course</p>
                    <p className="font-bold text-sm">{course?.title}</p>
                    <p className="text-xs text-muted-foreground mt-0.5">Track: {track?.title}</p>
                </div>

                <div className="space-y-2">
                    <label className="text-sm font-medium flex items-center gap-2">
                        <Icon name="Youtube" size={16} className="text-red-500" />
                        YouTube Video URL
                    </label>
                    <input
                        type="url"
                        value={youtubeUrl}
                        onChange={(e) => setYoutubeUrl(e.target.value)}
                        className="w-full px-4 py-3 bg-background border border-border rounded-xl text-sm font-mono"
                        placeholder="https://www.youtube.com/watch?v=..."
                    />
                    {youtubeUrl && (
                        <div className="flex items-center gap-2 mt-1">
                            {isValid ? (
                                <span className="text-xs text-emerald-500 font-bold flex items-center gap-1">
                                    <Icon name="CheckCircle2" size={12} />
                                    Valid YouTube URL — ID: {videoId}
                                </span>
                            ) : (
                                <span className="text-xs text-red-500 font-bold flex items-center gap-1">
                                    <Icon name="XCircle" size={12} />
                                    Invalid YouTube URL
                                </span>
                            )}
                        </div>
                    )}
                </div>

                {isValid && videoId && (
                    <div className="rounded-xl overflow-hidden border border-border bg-black aspect-video">
                        <img
                            src={`https://img.youtube.com/vi/${videoId}/mqdefault.jpg`}
                            alt="Video thumbnail"
                            className="w-full h-full object-cover opacity-80"
                        />
                    </div>
                )}

                <div className="flex items-center justify-between pt-4 border-t border-border">
                    {existingRecording?.youtube_video_id ? (
                        <Button
                            variant="outline"
                            onClick={handleRemove}
                            disabled={removing}
                            className="gap-1 text-xs text-red-500 border-red-500/20 hover:bg-red-500/10"
                        >
                            {removing ? (
                                <div className="animate-spin rounded-full h-3 w-3 border-t border-b border-current" />
                            ) : (
                                <Icon name="Trash2" size={12} />
                            )}
                            Remove Recording
                        </Button>
                    ) : (
                        <div />
                    )}
                    <div className="flex gap-2">
                        <Button variant="ghost" onClick={onClose}>
                            Cancel
                        </Button>
                        <Button onClick={handleSave} disabled={!isValid || saving}>
                            {saving ? (
                                <div className="animate-spin rounded-full h-4 w-4 border-t border-b border-current mr-2" />
                            ) : (
                                <Icon name="Link" size={14} className="mr-1" />
                            )}
                            {existingRecording?.youtube_video_id ? 'Update Recording' : 'Link Recording'}
                        </Button>
                    </div>
                </div>
            </div>
        </Modal>
    );
};

export default LinkRecordingModal;