import React, { useState, useEffect, useCallback } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { supabaseService } from '../../../services/supabaseService';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import Modal from '../../../components/ui/Modal';
import { useToast } from '../../../contexts/ToastContext';
import LinkRecordingModal from './LinkRecordingModal';

const CourseLiveSessions = () => {
    const navigate = useNavigate();
    const { addToast } = useToast();
    const user = useSelector((state) => state.auth.user);
    const tracks = useSelector((state) => state.content.academyTracks) || [];
    const courses = useSelector((state) => state.content.academy) || [];

    const [activeSessions, setActiveSessions] = useState([]);
    const [recordings, setRecordings] = useState({});
    const [loading, setLoading] = useState(true);
    const [startingSession, setStartingSession] = useState(null);
    const [linkingCourse, setLinkingCourse] = useState(null);
    const [expandedTrack, setExpandedTrack] = useState(null);

    const fetchData = useCallback(async () => {
        try {
            setLoading(true);
            const allCourseIds = tracks.flatMap(t => (t.courses || []).map(String));
            const sessions = allCourseIds.length > 0
                ? await supabaseService.getActiveSessionsForTrackCourses(allCourseIds)
                : [];
            setActiveSessions(sessions);

            const recsMap = {};
            for (const track of tracks) {
                const trackRecs = await supabaseService.getCourseRecordingsByTrack(track.id);
                trackRecs.forEach(r => { recsMap[r.course_id] = r; });
            }
            setRecordings(recsMap);
        } catch (err) {
            console.error('Failed to fetch live session data:', err);
        } finally {
            setLoading(false);
        }
    }, [tracks]);

    useEffect(() => { fetchData(); }, [fetchData]);

    const handleStartLiveSession = async (track, course) => {
        const sessionKey = `${track.id}-${course.id}`;
        setStartingSession(sessionKey);
        try {
            const session = await supabaseService.createLiveSession({
                title: `${course.title} — Live Class`,
                session_type: 'course_live',
                status: 'live',
                start_time: new Date().toISOString(),
                is_public: false,
                track_id: track.id,
                course_id: String(course.id),
                description: JSON.stringify({
                    _type: 'course_live',
                    _scope: 'track',
                    trackId: track.id,
                    trackTitle: track.title,
                    courseId: String(course.id),
                    courseTitle: course.title,
                }),
            });
            addToast(`Live session started for "${course.title}"!`, 'success');
            await fetchData();
            navigate(`/academy/live/${session.meeting_id}`);
        } catch (err) {
            console.error('Failed to start session:', err);
            addToast('Failed to start live session', 'error');
        } finally {
            setStartingSession(null);
        }
    };

    const handleEndSession = async (session) => {
        try {
            await supabaseService.updateLiveSessionStatus(session.id, 'ended');
            addToast('Session ended', 'success');
            await fetchData();
        } catch (err) {
            addToast('Failed to end session', 'error');
        }
    };

    const handleRecordingLinked = async () => {
        setLinkingCourse(null);
        await fetchData();
    };

    const getActiveSessionForCourse = (courseId) => {
        return activeSessions.find(s => String(s.course_id) === String(courseId));
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center py-20">
                <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-primary" />
            </div>
        );
    }

    return (
        <div className="space-y-6 p-4 md:p-6 overflow-hidden">
            <div>
                <h2 className="text-xl sm:text-2xl font-bold flex items-center gap-2">
                    <Icon name="Radio" size={24} className="text-secondary" />
                    Course Live Sessions
                </h2>
                <p className="text-sm text-muted-foreground mt-1">
                    Start live classes for track courses. Enrolled students can join in real-time. Recordings are linked manually after each session.
                </p>
            </div>

            {tracks.length === 0 ? (
                <div className="text-center py-12 bg-muted/20 rounded-2xl border border-dashed border-border">
                    <Icon name="Layers" size={32} className="mx-auto mb-3 opacity-30" />
                    <p className="text-sm font-bold text-muted-foreground">No tracks created yet.</p>
                    <p className="text-xs text-muted-foreground/60 mt-1">Create tracks in the "Academy Tracks" tab first.</p>
                </div>
            ) : (
                <div className="space-y-4">
                    {tracks.map((track) => {
                        const isExpanded = expandedTrack === track.id;
                        const trackCourseCount = (track.courses || []).length;
                        const activeCount = (track.courses || []).filter(cid => getActiveSessionForCourse(cid)).length;
                        const recordedCount = (track.courses || []).filter(cid => recordings[String(cid)]?.youtube_video_id).length;

                        return (
                            <div key={track.id} className="bg-card border border-border rounded-2xl overflow-hidden">
                                <button
                                    onClick={() => setExpandedTrack(isExpanded ? null : track.id)}
                                    className="w-full flex items-center justify-between p-5 text-left hover:bg-muted/30 transition-colors"
                                >
                                    <div className="flex items-center gap-4">
                                        <div className="w-10 h-10 rounded-xl bg-secondary/10 flex items-center justify-center">
                                            <Icon name="Layers" size={18} className="text-secondary" />
                                        </div>
                                        <div>
                                            <h3 className="font-bold text-sm">{track.title}</h3>
                                            <p className="text-xs text-muted-foreground">
                                                {trackCourseCount} course{trackCourseCount !== 1 ? 's' : ''}
                                                {activeCount > 0 && (
                                                    <span className="ml-2 text-red-500 font-bold">{activeCount} live</span>
                                                )}
                                                {recordedCount > 0 && (
                                                    <span className="ml-2 text-emerald-500 font-bold">{recordedCount} recorded</span>
                                                )}
                                            </p>
                                        </div>
                                    </div>
                                    <Icon
                                        name={isExpanded ? "ChevronUp" : "ChevronDown"}
                                        size={18}
                                        className="text-muted-foreground"
                                    />
                                </button>

                                {isExpanded && (
                                    <div className="border-t border-border">
                                        {(track.courses || []).length === 0 ? (
                                            <div className="p-4 md:p-6 text-center text-sm text-muted-foreground italic">
                                                No courses in this track.
                                            </div>
                                        ) : (
                                            <div className="divide-y divide-border">
                                                {(track.courses || []).map(courseId => {
                                                    const course = courses.find(c => String(c.id) === String(courseId));
                                                    if (!course) return null;

                                                    const activeSession = getActiveSessionForCourse(courseId);
                                                    const recording = recordings[String(courseId)];
                                                    const hasVideo = recording?.youtube_video_id;
                                                    const sessionKey = `${track.id}-${courseId}`;
                                                    const isStarting = startingSession === sessionKey;

                                                    return (
                                                        <div key={courseId} className="p-4 flex items-center justify-between gap-4">
                                                            <div className="flex-1 min-w-0">
                                                                <p className="font-bold text-sm truncate">{course.title}</p>
                                                                <div className="flex items-center gap-2 mt-1">
                                                                    {activeSession ? (
                                                                        <span className="inline-flex items-center gap-1 text-[10px] font-black uppercase tracking-widest text-red-500 bg-red-500/10 px-2 py-0.5 rounded-full">
                                                                            <span className="w-1.5 h-1.5 bg-red-500 rounded-full animate-pulse" />
                                                                            {activeSession.status === 'live' ? 'LIVE' : 'WAITING'}
                                                                        </span>
                                                                    ) : hasVideo ? (
                                                                        <span className="inline-flex items-center gap-1 text-[10px] font-black uppercase tracking-widest text-emerald-500 bg-emerald-500/10 px-2 py-0.5 rounded-full">
                                                                            <Icon name="CheckCircle2" size={10} />
                                                                            RECORDED
                                                                        </span>
                                                                    ) : (
                                                                        <span className="inline-flex items-center gap-1 text-[10px] font-black uppercase tracking-widest text-muted-foreground bg-muted px-2 py-0.5 rounded-full">
                                                                            NO CONTENT
                                                                        </span>
                                                                    )}
                                                                </div>
                                                            </div>

                                                            <div className="flex items-center gap-2 shrink-0">
                                                                {activeSession ? (
                                                                    <>
                                                                        <Button
                                                                            size="sm"
                                                                            onClick={() => navigate(`/academy/live/${activeSession.meeting_id}`)}
                                                                            className="gap-1 text-xs"
                                                                        >
                                                                            <Icon name="LogIn" size={12} />
                                                                            Join
                                                                        </Button>
                                                                        <Button
                                                                            size="sm"
                                                                            variant="outline"
                                                                            onClick={() => handleEndSession(activeSession)}
                                                                            className="gap-1 text-xs text-red-500 border-red-500/20 hover:bg-red-500/10"
                                                                        >
                                                                            End
                                                                        </Button>
                                                                    </>
                                                                ) : (
                                                                    <>
                                                                        <Button
                                                                            size="sm"
                                                                            onClick={() => handleStartLiveSession(track, course)}
                                                                            disabled={isStarting}
                                                                            className="gap-1 text-xs"
                                                                        >
                                                                            {isStarting ? (
                                                                                <div className="animate-spin rounded-full h-3 w-3 border-t border-b border-current" />
                                                                            ) : (
                                                                                <Icon name="Radio" size={12} />
                                                                            )}
                                                                            {isStarting ? 'Starting...' : 'Go Live'}
                                                                        </Button>
                                                                        <Button
                                                                            size="sm"
                                                                            variant="outline"
                                                                            onClick={() => setLinkingCourse({ track, course, recording })}
                                                                            className="gap-1 text-xs"
                                                                        >
                                                                            <Icon name="Link" size={12} />
                                                                            {hasVideo ? 'Update' : 'Link YT'}
                                                                        </Button>
                                                                    </>
                                                                )}
                                                            </div>
                                                        </div>
                                                    );
                                                })}
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            )}

            {linkingCourse && (
                <LinkRecordingModal
                    isOpen={!!linkingCourse}
                    onClose={() => setLinkingCourse(null)}
                    onLinked={handleRecordingLinked}
                    track={linkingCourse.track}
                    course={linkingCourse.course}
                    existingRecording={linkingCourse.recording}
                />
            )}
        </div>
    );
};

export default CourseLiveSessions;