import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import { useToast } from '../../../contexts/ToastContext';
import { cn } from '../../../utils/cn';
import ConfirmationModal from '../../../components/ui/ConfirmationModal';

const LiveSessionManagement = () => {
    const { addToast } = useToast();
    const [sessions, setSessions] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState('all'); // all, live, waiting, ended
    
    // Bulk Selection State
    const [selectedIds, setSelectedIds] = useState([]);
    
    // Confirmation Modal State
    const [confirmConfig, setConfirmConfig] = useState({
        isOpen: false,
        id: null,
        type: 'single' // 'single' or 'bulk'
    });

    const fetchSessions = async () => {
        try {
            setLoading(true);
            const data = await supabaseService.getAdminLiveSessions();
            setSessions(data);
            setSelectedIds([]); // Clear selection on refresh
        } catch (err) {
            console.error("Failed to fetch sessions", err);
            addToast("Failed to load sessions", "error");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchSessions();
    }, []);

    const handleUpdateStatus = async (id, status) => {
        try {
            await supabaseService.updateLiveSessionStatus(id, status);
            addToast(`Session ${status} successfully`, "success");
            
            // Broadcast approval if it went live or is now waiting (approved)
            if (status === 'live' || status === 'waiting') {
                const session = sessions.find(s => s.id === id);
                if (session) {
                    supabaseService.supabase.channel('platform_notifications').send({
                        type: 'broadcast',
                        event: 'SESSION_APPROVED',
                        payload: {
                            sessionId: id,
                            meetingId: session.meeting_id,
                            hostId: session.host_id,
                            invitedMemberIds: session.metadata?.invited_member_ids || [],
                            title: session.title,
                            status: status
                        }
                    });
                }
            }
            
            fetchSessions();
        } catch (err) {
            addToast(`Failed to update session to ${status}`, "error");
        }
    };

    const confirmPurge = async () => {
        const type = confirmConfig.type;
        const ids = type === 'bulk' ? selectedIds : [confirmConfig.id];
        setConfirmConfig({ isOpen: false, id: null, type: 'single' });
        
        try {
            // Use .select() to verify which rows actually updated under RLS
            const { data, error } = await supabaseService.supabase
                .from('live_sessions')
                .update({ status: 'purged' })
                .in('id', ids)
                .select();
            
            if (error) throw error;
            
            const updatedCount = data?.length || 0;
            const failedCount = ids.length - updatedCount;

            if (failedCount > 0) {
                if (updatedCount > 0) {
                    addToast(`Purged ${updatedCount} records, but ${failedCount} were refused by security policies.`, "warning");
                } else {
                    addToast("Purge refused. Your Admin account may lack RLS 'Update' permissions for these specific sessions.", "error");
                }
            } else {
                addToast(`${updatedCount} record(s) successfully purged from view.`, "success");
            }
            
            fetchSessions();
        } catch (err) {
            console.error("Purge Error:", err);
            addToast("Failed to communicate with database. Please try again.", "error");
        }
    };

    const handleDeleteClick = (id) => {
        setConfirmConfig({ isOpen: true, id, type: 'single' });
    };

    const handleBulkDeleteClick = () => {
        if (selectedIds.length === 0) return;
        setConfirmConfig({ isOpen: true, id: null, type: 'bulk' });
    };

    const toggleSelect = (id) => {
        setSelectedIds(prev => 
            prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
        );
    };

    const toggleSelectAll = () => {
        if (selectedIds.length === filteredSessions.length) {
            setSelectedIds([]);
        } else {
            setSelectedIds(filteredSessions.map(s => s.id));
        }
    };

    const filteredSessions = sessions.filter(s => {
        if (filter === 'all') return true;
        if (filter === 'pending') return s.status === 'pending';
        if (filter === 'live') return s.status === 'live';
        if (filter === 'waiting') return s.status === 'waiting';
        if (filter === 'ended') return s.status === 'ended' || s.status === 'cancelled';
        return true;
    });

    return (
        <div className="space-y-6 p-4 md:p-6 overflow-hidden">
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                <div>
                    <h2 className="text-xl font-bold flex items-center gap-2">
                        <Icon name="Radio" size={24} className="text-primary" />
                        Brainstorm Command Center
                    </h2>
                    <p className="text-xs text-muted-foreground">Monitor and moderate all live and scheduled brainstorm sessions.</p>
                </div>
                <div className="flex items-center gap-2">
                    {selectedIds.length > 0 && (
                        <Button 
                            variant="danger" 
                            size="sm" 
                            iconName="Trash2" 
                            onClick={handleBulkDeleteClick}
                            className="animate-in fade-in zoom-in duration-300"
                        >
                            Purge ({selectedIds.length})
                        </Button>
                    )}
                    <div className="flex bg-muted p-1 rounded-xl border border-border overflow-x-auto flex-nowrap">
                        {['all', 'pending', 'live', 'waiting', 'ended'].map((f) => (
                            <button
                                key={f}
                                onClick={() => setFilter(f)}
                                className={cn(
                                    "px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all",
                                    filter === f ? "bg-white dark:bg-gray-800 shadow-sm text-primary" : "text-muted-foreground hover:text-primary"
                                )}
                            >
                                {f}
                            </button>
                        ))}
                    </div>
                    <Button variant="outline" size="sm" iconName="RefreshCw" onClick={fetchSessions} loading={loading}>
                        Sync
                    </Button>
                </div>
            </div>

            <div className="bg-card border border-border rounded-2xl overflow-hidden shadow-sm">
                <div className="md:hidden divide-y divide-border">
                    {filteredSessions.length > 0 ? filteredSessions.map((session) => (
                        <div key={session.id} className={cn(
                            "p-4",
                            selectedIds.includes(session.id) && "bg-primary/5"
                        )}>
                            <div className="flex items-center gap-3">
                                <input 
                                    type="checkbox" 
                                    className="rounded border-border bg-background text-primary focus:ring-primary h-4 w-4 transition-all cursor-pointer flex-shrink-0"
                                    checked={selectedIds.includes(session.id)}
                                    onChange={() => toggleSelect(session.id)}
                                />
                                <img 
                                    src={session.host?.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(session.host?.full_name || 'H')}`} 
                                    className="w-10 h-10 rounded-xl object-cover border border-border flex-shrink-0"
                                    alt="Host"
                                />
                                <div className="flex-1 min-w-0">
                                    <p className="font-bold text-sm leading-tight text-primary truncate">{session.title}</p>
                                    <p className="text-[10px] text-muted-foreground uppercase font-bold tracking-tight truncate">By {session.host?.full_name || 'Anonymous'}</p>
                                    <p className="text-[9px] text-brand-blue font-mono mt-0.5">{session.meeting_id}</p>
                                </div>
                            </div>
                            <div className="flex items-center justify-between mt-3 gap-2">
                                <div className="flex items-center gap-2 flex-wrap min-w-0">
                                    <div className={cn(
                                        "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-black uppercase tracking-tighter border",
                                        session.status === 'live' ? "bg-red-500/10 text-red-600 border-red-500/20 animate-pulse" :
                                        session.status === 'pending' ? "bg-indigo-500/10 text-indigo-600 border-indigo-500/20 animate-pulse" :
                                        session.status === 'waiting' ? "bg-amber-500/10 text-amber-600 border-amber-500/20" :
                                        session.status === 'cancelled' ? "bg-gray-500/10 text-gray-500 border-gray-500/20" :
                                        "bg-slate-500/10 text-slate-500 border-slate-500/20"
                                    )}>
                                        <div className={cn("w-1.5 h-1.5 rounded-full", 
                                            session.status === 'live' ? "bg-red-500" : 
                                            session.status === 'pending' ? "bg-indigo-500" :
                                            session.status === 'waiting' ? "bg-amber-500" : 
                                            "bg-slate-500"
                                        )} />
                                        {session.status}
                                    </div>
                                    <p className="text-xs font-bold text-primary whitespace-nowrap">{new Date(session.start_time).toLocaleDateString()}</p>
                                    <p className="text-[10px] text-muted-foreground whitespace-nowrap">{new Date(session.start_time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                                </div>
                                <div className="flex items-center gap-1 flex-shrink-0">
                                    {session.status === 'pending' && (
                                        <button 
                                            onClick={() => handleUpdateStatus(session.id, new Date(session.start_time) <= new Date() ? 'live' : 'waiting')}
                                            className="w-11 h-11 flex items-center justify-center text-green-600 hover:bg-green-500/10 rounded-xl transition-all"
                                            title="Approve Session"
                                        >
                                            <Icon name="CheckCircle" size={18} />
                                        </button>
                                    )}
                                    {session.status === 'waiting' && (
                                        <button 
                                            onClick={() => handleUpdateStatus(session.id, 'live')}
                                            className="w-11 h-11 flex items-center justify-center text-blue-600 hover:bg-blue-500/10 rounded-xl transition-all"
                                            title="Go Live Now"
                                        >
                                            <Icon name="PlayCircle" size={18} />
                                        </button>
                                    )}
                                    {(session.status === 'live' || session.status === 'waiting' || session.status === 'pending') && (
                                        <button 
                                            onClick={() => handleUpdateStatus(session.id, 'cancelled')}
                                            className="w-11 h-11 flex items-center justify-center text-amber-600 hover:bg-amber-500/10 rounded-xl transition-all"
                                            title="Decline / Cancel"
                                        >
                                            <Icon name="Ban" size={18} />
                                        </button>
                                    )}
                                    <button 
                                        onClick={() => handleDeleteClick(session.id)}
                                        className="w-11 h-11 flex items-center justify-center text-slate-400 hover:text-red-600 hover:bg-red-500/10 rounded-xl transition-all"
                                        title="Purge Record"
                                    >
                                        <Icon name="Trash2" size={18} />
                                    </button>
                                </div>
                            </div>
                        </div>
                    )) : (
                        <div className="px-6 py-16 text-center">
                            <div className="flex flex-col items-center justify-center text-muted-foreground">
                                <Icon name="Inbox" size={40} className="mb-2 opacity-20" />
                                <p className="italic text-sm font-medium">No sessions found in this category.</p>
                            </div>
                        </div>
                    )}
                </div>
                <div className="overflow-x-auto hidden md:block">
                    <table className="w-full text-left">
                        <thead>
                            <tr className="bg-muted/50 border-b border-border">
                                <th className="px-4 py-4 w-10">
                                    <input 
                                        type="checkbox" 
                                        className="rounded border-border bg-background text-primary focus:ring-primary h-4 w-4 transition-all cursor-pointer"
                                        checked={filteredSessions.length > 0 && selectedIds.length === filteredSessions.length}
                                        onChange={toggleSelectAll}
                                    />
                                </th>
                                <th className="px-6 py-4 text-xs font-black uppercase tracking-widest text-muted-foreground">Session / Host</th>
                                <th className="px-6 py-4 text-xs font-black uppercase tracking-widest text-muted-foreground">Timing</th>
                                <th className="px-6 py-4 text-xs font-black uppercase tracking-widest text-muted-foreground">Status</th>
                                <th className="px-6 py-4 text-xs font-black uppercase tracking-widest text-muted-foreground text-right">Moderation</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {filteredSessions.length > 0 ? filteredSessions.map((session) => (
                                <tr key={session.id} className={cn(
                                    "hover:bg-muted/30 transition-colors",
                                    selectedIds.includes(session.id) && "bg-primary/5 hover:bg-primary/10"
                                )}>
                                    <td className="px-4 py-4">
                                        <input 
                                            type="checkbox" 
                                            className="rounded border-border bg-background text-primary focus:ring-primary h-4 w-4 transition-all cursor-pointer"
                                            checked={selectedIds.includes(session.id)}
                                            onChange={() => toggleSelect(session.id)}
                                        />
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-3">
                                            <img 
                                                src={session.host?.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(session.host?.full_name || 'H')}`} 
                                                className="w-10 h-10 rounded-xl object-cover border border-border"
                                                alt="Host"
                                            />
                                            <div>
                                                <p className="font-bold text-sm leading-tight text-primary">{session.title}</p>
                                                <p className="text-[10px] text-muted-foreground uppercase font-bold tracking-tight">By {session.host?.full_name || 'Anonymous'}</p>
                                                <p className="text-[9px] text-brand-blue font-mono mt-0.5">{session.meeting_id}</p>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="space-y-1">
                                            <p className="text-xs font-bold text-primary">{new Date(session.start_time).toLocaleDateString()}</p>
                                            <p className="text-[10px] text-muted-foreground">{new Date(session.start_time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className={cn(
                                            "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-black uppercase tracking-tighter border",
                                            session.status === 'live' ? "bg-red-500/10 text-red-600 border-red-500/20 animate-pulse" :
                                            session.status === 'pending' ? "bg-indigo-500/10 text-indigo-600 border-indigo-500/20 animate-pulse" :
                                            session.status === 'waiting' ? "bg-amber-500/10 text-amber-600 border-amber-500/20" :
                                            session.status === 'cancelled' ? "bg-gray-500/10 text-gray-500 border-gray-500/20" :
                                            "bg-slate-500/10 text-slate-500 border-slate-500/20"
                                        )}>
                                            <div className={cn("w-1.5 h-1.5 rounded-full", 
                                                session.status === 'live' ? "bg-red-500" : 
                                                session.status === 'pending' ? "bg-indigo-500" :
                                                session.status === 'waiting' ? "bg-amber-500" : 
                                                "bg-slate-500"
                                            )} />
                                            {session.status}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <div className="flex justify-end items-center gap-1">
                                            {session.status === 'pending' && (
                                                <button 
                                                    onClick={() => handleUpdateStatus(session.id, new Date(session.start_time) <= new Date() ? 'live' : 'waiting')}
                                                    className="p-2 text-green-600 hover:bg-green-500/10 rounded-xl transition-all"
                                                    title="Approve Session"
                                                >
                                                    <Icon name="CheckCircle" size={18} />
                                                </button>
                                            )}
                                            {session.status === 'waiting' && (
                                                <button 
                                                    onClick={() => handleUpdateStatus(session.id, 'live')}
                                                    className="p-2 text-blue-600 hover:bg-blue-500/10 rounded-xl transition-all"
                                                    title="Go Live Now"
                                                >
                                                    <Icon name="PlayCircle" size={18} />
                                                </button>
                                            )}
                                            {(session.status === 'live' || session.status === 'waiting' || session.status === 'pending') && (
                                                <button 
                                                    onClick={() => handleUpdateStatus(session.id, 'cancelled')}
                                                    className="p-2 text-amber-600 hover:bg-amber-500/10 rounded-xl transition-all"
                                                    title="Decline / Cancel"
                                                >
                                                    <Icon name="Ban" size={18} />
                                                </button>
                                            )}
                                            <button 
                                                onClick={() => handleDeleteClick(session.id)}
                                                className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-500/10 rounded-xl transition-all"
                                                title="Purge Record"
                                            >
                                                <Icon name="Trash2" size={18} />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            )) : (
                                <tr>
                                    <td colSpan="4" className="px-6 py-16 text-center">
                                        <div className="flex flex-col items-center justify-center text-muted-foreground">
                                            <Icon name="Inbox" size={40} className="mb-2 opacity-20" />
                                            <p className="italic text-sm font-medium">No sessions found in this category.</p>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            <ConfirmationModal 
                isOpen={confirmConfig.isOpen}
                onClose={() => setConfirmConfig({ isOpen: false, id: null, type: 'single' })}
                onConfirm={confirmPurge}
                title={confirmConfig.type === 'bulk' ? `Purge ${selectedIds.length} Records` : "Purge Session Record"}
                message={confirmConfig.type === 'bulk' 
                    ? `Are you sure you want to permanently hide these ${selectedIds.length} brainstorm sessions from all views? This action cannot be undone.`
                    : "Are you sure you want to permanently delete this brainstorm session log? This action cannot be undone."
                }
                confirmText={confirmConfig.type === 'bulk' ? "Purge All Selected" : "Purge Record"}
                cancelText="Keep Record"
                type="danger"
            />
        </div>
    );
};

export default LiveSessionManagement;
